package main

import (
	"bufio"
	"fmt"
	"math"
	"os"
)

const INF = 1000000000

var dx = [4]int{1, -1, 0, 0}
var dy = [4]int{0, 0, 1, -1}

func main() {
	in := bufio.NewScanner(os.Stdin)
	in.Split(bufio.ScanWords)

	nextInt := func() int {
		in.Scan()
		x := 0
		for _, c := range in.Bytes() {
			x = x*10 + int(c-'0')
		}
		return x
	}

	nextString := func() string {
		in.Scan()
		return in.Text()
	}

	n := nextInt()
	m := nextInt()

	a := make([][]byte, n+2)
	for i := 0; i <= n+1; i++ {
		a[i] = make([]byte, m+2)
		for j := 0; j <= m+1; j++ {
			a[i][j] = '#'
		}
	}

	sx, sy := 0, 0
	tx := [10]int{}
	ty := [10]int{}
	tp := [10]int{}
	tn := 0
	bx := [10]int{}
	by := [10]int{}
	bn := 0

	for i := 1; i <= n; i++ {
		s := nextString()
		for j := 1; j <= m; j++ {
			a[i][j] = s[j-1]
			ch := a[i][j]
			if ch == 'S' {
				sx, sy = i, j
			} else if ch >= '0' && ch <= '9' {
				d := int(ch - '0')
				tx[d] = i
				ty[d] = j
				tn++
			} else if ch == 'B' {
				bn++
				bx[bn] = i
				by[bn] = j
			}
		}
	}

	for i := 1; i <= tn; i++ {
		tp[i] = nextInt()
	}

	maxTMask := 1 << tn
	maxBMask := 1 << bn
	// f[x][y][tmask][bmask] flattened
	// dimensions: (n+1) * (m+1) * maxTMask * maxBMask
	// x in 1..n, y in 1..m
	strideX := (m + 1) * maxTMask * maxBMask
	strideY := maxTMask * maxBMask
	strideT := maxBMask
	totalSize := (n + 1) * strideX
	f := make([]int, totalSize)
	for i := range f {
		f[i] = INF
	}

	idx := func(x, y, t, b int) int {
		return x*strideX + y*strideY + t*strideT + b
	}

	qSize := 2000010
	qx := make([]int, qSize)
	qy := make([]int, qSize)
	qt := make([]int, qSize)
	qb := make([]int, qSize)
	l, r := 0, 0 // 0-based queue indices, [l, r)

	qx[r] = sx
	qy[r] = sy
	qt[r] = 0
	qb[r] = 0
	r++
	f[idx(sx, sy, 0, 0)] = 0

	for l < r {
		ox := qx[l]
		oy := qy[l]
		ot := qt[l]
		ob := qb[l]
		l++
		curDist := f[idx(ox, oy, ot, ob)]

		for k := 0; k < 4; k++ {
			nx := ox + dx[k]
			ny := oy + dy[k]
			nt := ot
			nb := ob

			if a[nx][ny] != '.' && a[nx][ny] != 'S' {
				continue
			}

			for i := 1; i <= tn; i++ {
				if ny <= ty[i] {
					continue
				}
				if nx == tx[i]-1 && ox == tx[i] {
					nt ^= (1 << (i - 1))
				}
				if ox == tx[i]-1 && nx == tx[i] {
					nt ^= (1 << (i - 1))
				}
			}

			for i := 1; i <= bn; i++ {
				if ny <= by[i] {
					continue
				}
				if nx == bx[i]-1 && ox == bx[i] {
					nb ^= (1 << (i - 1))
				}
				if ox == bx[i]-1 && nx == bx[i] {
					nb ^= (1 << (i - 1))
				}
			}

			id := idx(nx, ny, nt, nb)
			if f[id] > curDist+1 {
				f[id] = curDist + 1
				qx[r] = nx
				qy[r] = ny
				qt[r] = nt
				qb[r] = nb
				r++
			}
		}
	}

	pr := make([]int, maxTMask)
	for i := 0; i < maxTMask; i++ {
		for j := 1; j <= tn; j++ {
			if i&(1<<(j-1)) != 0 {
				pr[i] += tp[j]
			}
		}
	}

	ans := 0
	for i := 0; i < maxTMask; i++ {
		dist := f[idx(sx, sy, i, 0)]
		if dist != INF {
			val := pr[i] - dist
			if val > ans {
				ans = val
			}
		}
	}

	fmt.Println(ans)
}

